'use strict';
const {webcrypto}=require('node:crypto'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const {fixture:fixture16,A,B,C_ID,PASS,clone}=require('./i16-anchor-fixture.cjs');
const {b64}=require('./i13-witness-fixture.cjs');
function module17(){
 const x={crypto:webcrypto,TextEncoder,TextDecoder,atob,btoa,console};
 x.window=x;x.globalThis=x;vm.createContext(x);
 for(const file of ['i11-audit-core.js','i11-evidence.js','i12-manifest.js',
  'i13-witnesses.js','i14-policy-lifecycle.js','i15-recovery.js',
  'i16-anchors.js','i17-forensics.js']){
  vm.runInContext(fs.readFileSync(path.join(__dirname,'../lab',file),'utf8'),
   x,{filename:file});
 }
 return {F:x.MiBowlingI17Forensics,K:x.MiBowlingI16Anchors};
}
async function fixture(owner=A){
 const f=await fixture16(owner),{F,K}=module17();
 const reports=['A','B','C'].map((slot,i)=>({
  slot,history:clone(f.history),copy:clone(f.copies[i])
 }));
 const branch=async(slot='C')=>{
  const history=clone(f.history),last=history.records.at(-1);
  const st={...last.statement,nonce:'88888888-1616-4161-8161-000000000017'};
  const signatures=[];
  for(let j=0;j<2;j++){
   const bytes=await webcrypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},
     f.previous.fresh.pairs[j].privateKey,K.signBytes(st));
   signatures.push({keyId:f.source.newPolicy.keys[j].keyId,signature:b64(bytes)});
  }
  last.statement=st;last.signatures=signatures;
  const mark=await K.highWatermark(history,f.externalRoot);
  return {slot,history,copy:await K.anchorCopy(slot,mark)};
 };
 const stale=async(slot='C',generation=2)=>{
  const history=f.older(generation),mark=await K.highWatermark(history,f.externalRoot);
  return {slot,history,copy:await K.anchorCopy(slot,mark)};
 };
 return {...f,F,K,reports,branch,stale};
}
module.exports={fixture,A,B,C_ID,PASS,clone,module17};
